#!/usr/bin/env python3
"""lansee 多仓库管理：feature 从 dev 创建，发布使用 promote-dev。
代码及设计同步使用 sync-dev；运行 --help 查看入口。
"""

import argparse
import os
import shutil
import subprocess
import sys
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent
MASTER_DIR = BASE_DIR / "master"
DEV_DIR = BASE_DIR / "dev"
TEMPLATES_DIR = BASE_DIR / ".agent_templates"


def list_repos():
    """返回 master/ 下所有包含 .git 的仓库名"""
    if not MASTER_DIR.exists():
        return []
    return sorted(
        d.name
        for d in MASTER_DIR.iterdir()
        if d.is_dir() and (d / ".git").exists() and d.name != "ai-skin-backend"
    )


def detect_repo_type(repo_path):
    """自动识别仓库类型: python / java / js / unknown"""
    if (repo_path / "pyproject.toml").exists() or (repo_path / "requirements.txt").exists():
        return "python"
    if (repo_path / "pom.xml").exists() or (repo_path / "build.gradle").exists() or (repo_path / "build.gradle.kts").exists():
        return "java"
    if (repo_path / "package.json").exists():
        return "js"
    return "unknown"


def init_deps(repo_path):
    """尝试安装依赖，失败不中断"""
    rtype = detect_repo_type(repo_path)
    name = repo_path.name
    try:
        if rtype == "python":
            if (repo_path / "pyproject.toml").exists():
                subprocess.run(["uv", "sync"], cwd=repo_path, check=True)
            elif (repo_path / "requirements.txt").exists():
                subprocess.run(["uv", "init"], cwd=repo_path, check=True)
                subprocess.run(["uv", "add", "-r", "requirements.txt"], cwd=repo_path, check=True)
        elif rtype == "java":
            if (repo_path / "pom.xml").exists():
                subprocess.run(["mvn", "clean", "compile", "-DskipTests"], cwd=repo_path, check=True)
            elif (repo_path / "build.gradle").exists() or (repo_path / "build.gradle.kts").exists():
                subprocess.run(["./gradlew", "compileJava"], cwd=repo_path, check=True)
        elif rtype == "js":
            subprocess.run(["npm", "install"], cwd=repo_path, check=True)
        else:
            return
    except subprocess.CalledProcessError:
        print(f"[WARNING] {name} 依赖自动安装失败，请进入目录手动排查修复。", file=sys.stderr)


def inject_ide_config(repo_path):
    """从 .agent_templates/ 拷贝对应 IDE 配置"""
    rtype = detect_repo_type(repo_path)
    template_map = {
        "python": "pycharm_idea",
        "java": "intellij_idea",
        "js": "vscode_settings",
    }
    template_subdir = template_map.get(rtype)
    if not template_subdir:
        return
    template_dir = TEMPLATES_DIR / template_subdir
    if not template_dir.exists():
        return
    for item in template_dir.iterdir():
        dest = repo_path / item.name
        if not dest.exists():
            try:
                if item.is_dir():
                    shutil.copytree(item, dest)
                else:
                    shutil.copy2(item, dest)
            except OSError as e:
                print(f"[WARNING] 拷贝 IDE 配置失败: {item.name} -> {dest}: {e}", file=sys.stderr)


def _get_base_branch(repo_path):
    """获取仓库的基分支名，优先 master，其次 main，最后 HEAD"""
    for branch in ("master", "main"):
        result = subprocess.run(
            ["git", "rev-parse", "--verify", branch],
            cwd=repo_path, capture_output=True, text=True,
        )
        if result.returncode == 0:
            return branch
    result = subprocess.run(
        ["git", "rev-parse", "--abbrev-ref", "HEAD"],
        cwd=repo_path, capture_output=True, text=True,
    )
    return result.stdout.strip()


def _create_worktree(master_repo, target, branch, repo_name):
    """创建一个 worktree，返回 True 表示成功"""
    base = "dev"
    from workspace_flow import git
    git(master_repo, 'show-ref', '--verify', 'refs/heads/dev')
    try:
        subprocess.run(
            ["git", "worktree", "add", str(target), "-b", branch, base],
            cwd=master_repo, check=True, capture_output=True, text=True,
        )
        return True
    except subprocess.CalledProcessError as e:
        err_msg = e.stderr.strip()
        if "already exists" in err_msg or "已经存在" in err_msg:
            print(f"[WARNING] {repo_name}: 分支 {branch} 已存在，尝试直接检出", file=sys.stderr)
            try:
                subprocess.run(
                    ["git", "worktree", "add", str(target), branch],
                    cwd=master_repo, check=True,
                )
                return True
            except subprocess.CalledProcessError:
                print(f"[ERROR] {repo_name}: worktree 创建失败", file=sys.stderr)
                return False
        else:
            print(f"[ERROR] {repo_name}: {err_msg}", file=sys.stderr)
            return False


def cmd_start_feature(args):
    feature_dir = BASE_DIR / f"feature-{args.feature_name}"
    repos = [r.strip() for r in args.repos.split(",")] if args.repos else list_repos()

    if not repos:
        print("[ERROR] master/ 下没有可用的仓库", file=sys.stderr)
        return

    feature_dir.mkdir(exist_ok=True)

    for repo in repos:
        master_repo = MASTER_DIR / repo
        if not (master_repo / ".git").exists():
            print(f"[ERROR] 仓库 {repo} 不存在于 master/ 中，跳过", file=sys.stderr)
            continue

        target = feature_dir / repo
        if target.exists():
            print(f"[WARNING] {target} 已存在，跳过", file=sys.stderr)
            continue

        branch = f"feature/{args.feature_name}"
        print(f"[INFO] 为 {repo} 创建 worktree: {target} (分支: {branch})")

        if not _create_worktree(master_repo, target, branch, repo):
            continue

        inject_ide_config(target)
        init_deps(target)

    print(f"[DONE] feature-{args.feature_name} 创建完成")


def cmd_add_repo(args):
    feature_dir = BASE_DIR / f"feature-{args.feature_name}"

    if not feature_dir.exists():
        print(f"[ERROR] feature-{args.feature_name} 目录不存在，请先用 start-feature 创建", file=sys.stderr)
        return

    repos = [r.strip() for r in args.repos.split(",")] if args.repos else list_repos()

    for repo in repos:
        master_repo = MASTER_DIR / repo
        if not (master_repo / ".git").exists():
            print(f"[ERROR] 仓库 {repo} 不存在于 master/ 中，跳过", file=sys.stderr)
            continue

        target = feature_dir / repo
        if target.exists():
            print(f"[WARNING] {target} 已存在，跳过", file=sys.stderr)
            continue

        branch = f"feature/{args.feature_name}"
        print(f"[INFO] 为 {repo} 添加 worktree: {target} (分支: {branch})")

        if not _create_worktree(master_repo, target, branch, repo):
            continue

        inject_ide_config(target)
        init_deps(target)

    print(f"[DONE] 仓库已添加到 feature-{args.feature_name}")


def cmd_release_cleanup(args):
    """清理 feature worktree 和目录（不合并代码）"""
    repos = [r.strip() for r in args.repos.split(",")] if args.repos else list_repos()
    feature_name = args.feature_name
    feature_dir = BASE_DIR / f"feature-{feature_name}"

    for repo in repos:
        master_repo = MASTER_DIR / repo
        if not master_repo.exists():
            print(f"[ERROR] master/{repo} 不存在，跳过", file=sys.stderr)
            continue

        worktree_path = feature_dir / repo
        if not worktree_path.exists():
            print(f"[INFO] {repo}: worktree 不存在，跳过", file=sys.stderr)
            continue

        print(f"[INFO] {repo}: 清理 worktree")
        try:
            subprocess.run(["git", "worktree", "remove", str(worktree_path)], cwd=master_repo, check=True)
        except subprocess.CalledProcessError:
            print(f"[WARNING] {repo}: worktree 清理失败，请手动执行 git worktree remove {worktree_path}", file=sys.stderr)

    # 清理空的 feature 目录
    try:
        remaining = [p for p in feature_dir.iterdir()] if feature_dir.exists() else []
        if not remaining:
            feature_dir.rmdir()
    except OSError:
        pass

    print(f"[DONE] feature-{feature_name} worktree 已清理")


def _get_active_worktree_branches(repo_path):
    """返回该仓库当前有活跃 worktree 的分支名集合"""
    branches = set()
    try:
        result = subprocess.run(
            ["git", "worktree", "list", "--porcelain"],
            cwd=repo_path, capture_output=True, text=True, check=True,
        )
        for line in result.stdout.strip().splitlines():
            if line.startswith('branch refs/heads/'):
                branches.add(line.removeprefix('branch refs/heads/'))
    except subprocess.CalledProcessError:
        pass
    return branches


