import pathlib,json,urllib.request,urllib.parse,base64,threading,queue,time,datetime,os
R=pathlib.Path(__file__).parent
S=json.load(open(R/'status.json')); ROOT=S['sessionId']; W=S['worktree']; BASE=S['server']; Q=queue.Queue(); seen=set(); ids={ROOT}; idle=None
H={'Authorization':'Basic '+base64.b64encode(('opencode:'+(R/'server.password').read_text()).encode()).decode()}
opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
def request(p):return opener.open(urllib.request.Request(BASE+p+'?directory='+urllib.parse.quote(W),headers=H),timeout=40)
def get(p):
 with request(p) as f:return json.load(f)
def emit(x):print(json.dumps(x,ensure_ascii=False),flush=True)
def selected(e,scope):
 p=e.get('properties',{});sid=p.get('sessionID') or p.get('info',{}).get('id');return sid in scope and e.get('type') in ['permission.asked','question.asked','session.error','session.idle','session.status']
def once(key,data):
 if key not in seen:seen.add(key);emit(data)
def snapshot():
 global ids,idle
 all=get('/session');scope={ROOT}
 for _ in all:
  new={a['id'] for a in all if a.get('parentID') in scope and a.get('directory')==W};old=len(scope);scope|=new
  if old==len(scope):break
 ids=scope
 pending=[]
 for endpoint in ['/permission','/question']:
  for p in get(endpoint):
   if p.get('sessionID') in ids:
    pending.append(p['id']);once(p['id'],{'kind':endpoint[1:],'request':p})
 status=get('/session/status');busy=[i for i in ids if status.get(i,{}).get('type','idle')!='idle']
 for i in busy:
  if status[i].get('type')=='retry':once('retry:'+i+json.dumps(status[i]),{'kind':'retry','sessionID':i,'status':status[i]})
 if not busy and not pending:
  idle=idle or time.monotonic()
  if time.monotonic()-idle>10:once('idle:'+','.join(sorted(ids)),{'kind':'idle_candidate','sessions':sorted(ids)})
 else:idle=None
 return {'sessions':len(ids),'pending':len(pending),'active':len(busy)}
def stream():
 try:
  with request('/event') as f:
   Q.put({'type':'observer.connected','properties':{'status':f.status}})
   for raw in f:
    if raw.startswith(b'data: '):
     e=json.loads(raw[6:]);t=e.get('type','')
     if t=='server.connected':Q.put({'type':'observer.handshake'})
     elif t in ['permission.asked','question.asked','session.error','session.idle','session.status','session.created']:Q.put(e)
 except Exception as e:Q.put({'type':'observer.error','error':type(e).__name__})
assert selected({'type':'permission.asked','properties':{'sessionID':ROOT}},ids)
