assert not selected({'type':'permission.asked','properties':{'sessionID':'other'}},ids)
emit({'kind':'observer_selftest','scopeAndTokenFilter':'passed','dedupUsesRequestId':True})
emit({'kind':'beforeSubscription','snapshot':snapshot()})
threading.Thread(target=stream,daemon=True).start();last=time.monotonic()
while True:
 current=json.load(open(R/'status.json'))
 if current.get('phase')=='paused_by_user' or current.get('mode') not in ['realtime'] or (R/'PAUSED_BY_USER').exists():emit({'kind':'observer_stopped','reason':'pause or mode change'});break
 try:e=Q.get(timeout=2)
