   206	    private Accepted acceptA02New(PrincipalContext principal, IdempotencyHandle handle, UUID taskId,
   207	                                  String photoVersion, ParsedA02 parsed) {
   208	        UUID gimbalId = principal.gimbalUuid();
   209	        Map<String, MediaIntakeService.IngestedMedia> ingested;
   210	        try {
   250	                return reject(handle, ErrorCode.PHOTO_VERSION_CONFLICT,
   251	                        "photo version does not follow the current version");
   252	            }
   253	            long newVersion = current + 1;
   254	            long newRevision = row.processingRevision() + 1;
   255	
   256	            Map<String, String> merged = new LinkedHashMap<>(
   257	                    photoVersions.imagesAtVersion(row.photoVersions(), current));
   258	            for (String view : newMediaIds.keySet()) {
   259	                merged.put(view, newMediaIds.get(view));
   260	            }
   261	            // 防御不变量：PhotoVersions.append 会静默丢弃缺失视角，合并清单必须
   262	            // 恰好覆盖 front/left/right，否则拒绝追加（事务内抛 → 整体回滚）。
   263	            if (!merged.keySet().equals(Set.of("front", "left", "right"))
   264	                    || merged.values().stream().anyMatch(Objects::isNull)) {
   265	                throw new ApiException(ErrorCode.INTERNAL,
   266	                        "prior photo_versions view set is incomplete; refusing to append a"
   267	                                + " partial version");
   268	            }
   269	            String newPhotoVersions = photoVersions.append(row.photoVersions(), newVersion, merged);
   270	            int updated = assessmentRepository.updateRetake(taskId, newPhotoVersions, newVersion,
   271	                    newRevision);
   272	            if (updated != 1) {
   273	                throw new ApiException(ErrorCode.INTERNAL, "retake update failed");
   274	            }
   275	            for (String mediaId : newMediaIds.values()) {
   276	                int claimed = mediaRepository.claim(UUID.fromString(mediaId), taskId, newVersion,
   277	                        handle.requestId());
   278	                if (claimed != 1) {
   279	                    throw new ApiException(ErrorCode.INTERNAL, "media ownership claim failed");
   280	                }
   281	            }
   282	            jobEnqueuer.enqueue(JOB_TYPE, "assessment", taskId, newRevision,
   283	                    analyzePayload(taskId, newRevision),
   284	                    "assessment:" + taskId + ":" + newRevision);
   285	            idempotencyService.completeSuccess(handle, "skin_assessment", taskId,
   286	                    summary(taskId, String.valueOf(newVersion), "queued"));
   287	            return TxOutcome.accepted(new AssessmentTaskAccepted(
   288	                    taskId.toString(), "queued", String.valueOf(newVersion),
   289	                    String.valueOf(gimbal.currentAssessmentRevision())));
   290	            });
   291	        } catch (RuntimeException e) {
   292	            mediaCleanupEnqueuer.enqueueOrphansFor(handle.requestId());
   293	            throw e;
   294	        }
   295	
   296	        return finish(outcome, handle.requestId());
   297	    }
   298	
   299	    // ------------------------------------------------------------- helpers
   300	
   301	    private Accepted finish(TxOutcome outcome, UUID t13RequestId) {
   302	        if (outcome.rejectionCode() != null) {
   303	            // 确定性拒绝已提交：未接纳图片入队 media.cleanup（尽力而为，绝不上抛）
   304	            mediaCleanupEnqueuer.enqueueOrphansFor(t13RequestId);
   305	            throw new ApiException(outcome.rejectionCode(), outcome.rejectionMessage());
   306	        }
   307	        return new Accepted(outcome.data(), false);
   308	    }
   309	
   310	    /** 事务内确定性拒绝：写 T13 rejected 后返回拒绝结果（异常在提交后抛）。 */
   311	    private TxOutcome reject(IdempotencyHandle handle, ErrorCode code, String message) {
   312	        idempotencyService.completeRejected(handle, code, code.defaultStatus().value(),
   313	                message, false, null);
   314	        return TxOutcome.rejected(code, message);
   315	    }
   316	
   317	    private static Map<String, String> mediaIds(
   318	            Map<String, MediaIntakeService.IngestedMedia> ingested) {
   319	        Map<String, String> out = new LinkedHashMap<>();
   320	        ingested.forEach((part, media) -> out.put(part, media.media().id().toString()));
   321	        return out;
   322	    }
   323	
   324	    private static Map<String, Object> analyzePayload(UUID taskId, long processingRevision) {
   325	        Map<String, Object> payload = new LinkedHashMap<>();
   326	        payload.put("schema_version", 1);
   327	        payload.put("assessment_id", taskId.toString());
   328	        payload.put("processing_revision", String.valueOf(processingRevision));
   329	        return payload;
   330	    }
   331	
   332	    private static Map<String, Object> summary(UUID taskId, String photoVersion, String status) {
   333	        Map<String, Object> summary = new LinkedHashMap<>();
   334	        summary.put("schema_version", 1);
   335	        summary.put("task_id", taskId.toString());
   336	        summary.put("photo_version", photoVersion);
   337	        summary.put("status", status);
   338	        return summary;
   339	    }
   340	
   341	    /** 从 T13 存储摘要重建受理响应（不重做写入、不切指针）。 */
   342	    private static AssessmentTaskAccepted projectAccepted(JsonNode summary) {
   343	        return new AssessmentTaskAccepted(
   344	                summary.path("task_id").asText(null),
   345	                summary.path("status").asText("queued"),
   346	                summary.path("photo_version").asText(null),
   347	                null);
   348	    }
   349	
   350	    private static Long parseLong(String value) {
   351	        if (value == null) {
   352	            return null;
   353	        }
   354	        try {
   355	            return Long.parseLong(value);
   356	        } catch (NumberFormatException e) {
   357	            return null;
   358	        }
   359	    }
   360	}

