#!/usr/bin/env python3
"""Read-only, bounded OpenCode polling fallback. Standard library only."""
import argparse
import base64
import ipaddress
import json
import math
import os
from pathlib import Path
import re
import stat
import sys
import time
import urllib.error
import urllib.parse
import urllib.request


class PollError(Exception):
    pass


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        raise PollError('redirect_refused')


class Client:
    def __init__(self, server, directory, password, username='opencode'):
        u = urllib.parse.urlsplit(server)
        try:
            local = u.hostname == 'localhost' or ipaddress.ip_address(u.hostname).is_loopback
        except ValueError:
            local = False
        if (u.scheme not in ('http', 'https') or not local or u.username or
                u.password or u.path not in ('', '/') or u.query or u.fragment):
            raise PollError('server_must_be_loopback_origin')
        self.server = server.rstrip('/')
        self.directory = directory
        self.auth = 'Basic ' + base64.b64encode((username + ':' + password).encode()).decode()
        self.opener = urllib.request.build_opener(urllib.request.ProxyHandler({}), NoRedirect())
        self.deadline = float('inf')

    def get(self, path):
        remaining = self.deadline - time.monotonic()
        if remaining <= 0:
            raise TimeoutError()
        url = self.server + path + '?' + urllib.parse.urlencode({'directory': self.directory})
        req = urllib.request.Request(url, headers={'Authorization': self.auth}, method='GET')
        try:
            with self.opener.open(req, timeout=min(5, remaining)) as response:
                raw = response.read(4 * 1024 * 1024 + 1)
            if len(raw) > 4 * 1024 * 1024:
                raise PollError('response_too_large')
            return json.loads(raw)
        except urllib.error.HTTPError as e:
            raise PollError('http_' + str(e.code)) from None
        except urllib.error.URLError:
            raise PollError('connection_failed') from None
        except (ValueError, UnicodeError):
            raise PollError('invalid_json') from None


def state(path):
    value = json.loads(path.read_text())
    if not isinstance(value, dict):
        raise PollError('invalid_state')
    return value


def paused(path, marker):
    return marker.exists() or state(path).get('phase') == 'paused_by_user'


def session_ids(rows, root, directory):
    if not isinstance(rows, list):
        raise PollError('unsupported_session_schema')
    ids = {root}
    changed = True
    while changed:
        changed = False
        for row in rows:
            if not isinstance(row, dict):
                raise PollError('unsupported_session_schema')
            if row.get('directory') == directory and row.get('parentID') in ids and row.get('id') not in ids:
                if not isinstance(row.get('id'), str):
                    raise PollError('unsupported_session_schema')
                ids.add(row['id'])
                changed = True
    return ids


def sanitize(value, password):
    """Best-effort redaction. Changed/truncated details must never authorize an action."""
    raw = json.dumps(value, ensure_ascii=False)
    clean = raw.replace(password, '[REDACTED]') if password else raw
    clean = re.sub(r'(?i)Bearer\s+[A-Za-z0-9._~+/=-]+', 'Bearer [REDACTED]', clean)
    clean = re.sub(r'(?i)((?:password|secret|token|authorization|api[_-]?key)[\\"\s:=]+)[^\s,;\\"}]+', r'\1[REDACTED]', clean)
    changed = clean != raw
    if len(clean) > 2000:
        return {'preview': clean[:2000], 'requires_more_detail': True}
    try:
        result = json.loads(clean)
    except ValueError:
        return {'preview': clean, 'requires_more_detail': True}
    return {'request': result, 'requires_more_detail': changed}


def snapshot(client, root, directory, password):
    ids = session_ids(client.get('/session'), root, directory)
    events = []
    rows = client.get('/permission')
    if not isinstance(rows, list):
        raise PollError('unsupported_pending_schema')
    for row in rows:
        if not isinstance(row, dict) or not isinstance(row.get('sessionID'), str):
            raise PollError('unsupported_pending_schema')
        if row['sessionID'] not in ids:
            continue
        md = row.get('metadata', {})
        if not isinstance(md, dict):
            raise PollError('unsupported_permission_metadata')
        detail = {k: row[k] for k in ('permission', 'patterns', 'always') if k in row}
        detail['metadata'] = {k: md[k] for k in ('filepath', 'command', 'directories') if k in md}
        item = {'kind': 'permission', 'requestId': row.get('id'), 'sessionId': row['sessionID']}
        item.update(sanitize(detail, password))
        events.append(item)
    statuses = client.get('/session/status')
    if not isinstance(statuses, dict):
        raise PollError('unsupported_status_schema')
    active = []
    for sid in ids:
        st = statuses.get(sid, {'type': 'idle'})
        if not isinstance(st, dict) or st.get('type') not in ('idle', 'busy', 'retry'):
            raise PollError('unsupported_status_schema')
        if st['type'] != 'idle':
            active.append(st['type'])
    return events, bool(active)


def poll(client, root, directory, password, state_path, marker, interval, max_wait, idle_grace):
    deadline = time.monotonic() + max_wait
    client.deadline = deadline
    idle_since = None
    if paused(state_path, marker):
        return {'event': 'paused'}, 0
    doc = client.get('/doc')
    required = ['/session', '/session/status', '/permission', '/session/{sessionID}']
    paths = doc.get('paths', {})
    if any('get' not in paths.get(p, {}) for p in required):
        raise PollError('unsupported_api_check_runtime_doc')
    session = client.get('/session/' + urllib.parse.quote(root, safe=''))
    if session.get('id') != root or session.get('directory') != directory:
        raise PollError('root_session_directory_mismatch')
    while time.monotonic() < deadline:
        if paused(state_path, marker):
            return {'event': 'paused'}, 0
        current = state(state_path)
        if isinstance(current.get('server'), str):
            current['server'] = current['server'].rstrip('/')
        if any(current.get(k) != v for k, v in [('sessionId', root), ('worktree', directory), ('server', client.server)]):
            raise PollError('state_target_changed')
        events, active = snapshot(client, root, directory, password)
        if paused(state_path, marker):
            return {'event': 'paused'}, 0
        if events:
            return {'event': 'attention', 'items': events[:8], 'more_pending': len(events) > 8}, 0
        now = time.monotonic()
        if active:
            idle_since = None
        else:
            idle_since = now if idle_since is None else idle_since
            if now - idle_since >= idle_grace:
                return {'event': 'idle_candidate', 'sessionId': root,
                        'note': 'Not proof of completion; verify Git/handoff or a minimal error.'}, 0
        # One-second pause responsiveness, without any model or HTTP calls here.
        end = min(deadline, now + interval)
        while time.monotonic() < end:
            if paused(state_path, marker):
                return {'event': 'paused'}, 0
            time.sleep(min(1, max(0, end - time.monotonic())))
    return None, 0


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--state', type=Path, required=True, help='Authorized status.json (read-only)')
    parser.add_argument('--password-file', type=Path, required=True, help='Protected credential file; password never printed')
    parser.add_argument('--username', default='opencode')
    parser.add_argument('--pause-file', type=Path, help='Default: PAUSED_BY_USER alongside state')
    parser.add_argument('--interval', type=float, default=8)
    parser.add_argument('--max-wait', type=float, default=50, help='Seconds; choose within host tool timeout')
    parser.add_argument('--idle-grace', type=float, default=10)
    args = parser.parse_args()
    try:
        if (not all(math.isfinite(v) for v in (args.interval, args.max_wait, args.idle_grace))
                or args.interval <= 0 or args.max_wait <= 0 or args.idle_grace < 0):
            raise PollError('invalid_timing')
        info = state(args.state)
        marker = args.pause_file or args.state.parent / 'PAUSED_BY_USER'
        if paused(args.state, marker):
            print(json.dumps({'event': 'paused'}))
            return 0
        mode = args.password_file.stat()
        if not stat.S_ISREG(mode.st_mode) or mode.st_mode & 0o077 or mode.st_uid != os.getuid():
            raise PollError('credential_file_must_be_owned_and_private')
        password = args.password_file.read_text().rstrip('\r\n')
        if not password:
            raise PollError('empty_credential')
        root, directory, server = (info[k] for k in ('sessionId', 'worktree', 'server'))
        if not isinstance(root, str) or not root.startswith('ses') or not Path(directory).is_absolute():
            raise PollError('invalid_target')
        client = Client(server, directory, password, args.username)
        result, code = poll(client, root, directory, password, args.state, marker,
                            args.interval, args.max_wait, args.idle_grace)
        if result is not None:
            print(json.dumps(result, ensure_ascii=False), flush=True)
        return code
    except TimeoutError:
        print(json.dumps({'event': 'observer_error', 'reason': 'request_timeout'}))
        return 2
    except PollError as e:
        print(json.dumps({'event': 'observer_error', 'reason': str(e)}))
        return 2
    except KeyboardInterrupt:
        return 130
    except Exception:
        # Do not print raw URLs, credentials, private file contents or exception traces.
        print(json.dumps({'event': 'observer_error', 'reason': 'invalid_state_or_io_failure'}))
        return 2


if __name__ == '__main__':
    sys.exit(main())

